/// <reference types="node" />

import type { OutputFormat, Output, StrictUint8Array } from './types'

export interface ChachaOptions<F extends OutputFormat = 'uint8'> {
  key: StrictUint8Array
  data: StrictUint8Array
  nonce: StrictUint8Array
  additionalData?: StrictUint8Array
  format?: F
}

export function encryptChacha20poly1305<F extends OutputFormat = 'uint8'>(
  options: ChachaOptions<F>
): Promise<Output<F>>

export function decryptChacha20poly1305<F extends OutputFormat = 'uint8'>(
  options: ChachaOptions<F>
): Promise<Output<F>>

export function encryptXchacha20poly1305<F extends OutputFormat = 'uint8'>(
  options: ChachaOptions<F>
): Promise<Output<F>>

export function decryptXchacha20poly1305<F extends OutputFormat = 'uint8'>(
  options: ChachaOptions<F>
): Promise<Output<F>>
